mapper.select:
WITH T0 AS ( SELECT DISTINCT SORDERQ.YSOH_PJT_0 AS ProjectNO FROM EXPLOIT.SORDERQ SORDERQ INNER JOIN EXPLOIT.SORDER SORDER ON SORDERQ.SOHNUM_0 = SORDER.SOHNUM_0 WHERE UPPER(SORDERQ.YSOH_PJT_0) LIKE UPPER(#{ProjectNO}) + '%'
UNION ALL SELECT DISTINCT SORDERQ.YSOQ_PJTORI_0 AS ProjectNO FROM EXPLOIT.SORDERQ SORDERQ INNER JOIN EXPLOIT.SORDER SORDER ON SORDERQ.SOHNUM_0 = SORDER.SOHNUM_0 WHERE UPPER(SORDERQ.YSOQ_PJTORI_0) LIKE UPPER(#{ProjectNO}) + '%'
) SELECT ProjectNO FROM T0 ORDER BY ProjectNO ASC OFFSET #{offset} ROWS FETCH NEXT #{limit} ROWS ONLY
